$port=3000;$l=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Any,$port);$l.Start();Write-Host 'Server: http://localhost:3000' -F Green;$ip=(Get-NetIPAddress -AddressFamily IPv4|Where-Object{$_.IPAddress -notmatch '^(127|169)'}|Select-Object -First 1).IPAddress;Write-Host ('Network: http://'+$ip+':3000') -F Yellow;while($true){$c=$l.AcceptTcpClient();$s=$c.GetStream();$r=New-Object IO.StreamReader($s);$req=$r.ReadLine();if(!$req){$c.Close();continue};$p=[Uri]::UnescapeDataString(($req.Split(' '))[1].TrimStart('/'));if(!$p){$p='.'};$f=Join-Path (Get-Location) $p;if(Test-Path $f){if((Get-Item $f).PSIsContainer){$items=Get-ChildItem $f|ForEach-Object{$n=$_.Name;if($p -eq '.'){$u=$n}else{$u=$p+'/'+$n};$u=$u.Replace('\\','/');if($_.PSIsContainer){$n+='/'};'<li><a href=\"/'+$u+'\">'+$n+'</a></li>'};$h='<html><head><meta charset=UTF-8><style>body{font-family:Segoe UI;margin:20px;background:#1e1e1e;color:#ccc}a{color:#569cd6;text-decoration:none;font-size:18px}ul{list-style:none;padding:0}li{padding:8px 0;border-bottom:1px solid #333}</style></head><body><h2>/'+$p+'</h2><ul>'+($items -join '')+'</ul></body></html>';$b=[Text.Encoding]::UTF8.GetBytes($h);$hd="HTTP/1.1 200 OK`r`nContent-Type: text/html`r`nContent-Length: $($b.Length)`r`n`r`n";$hb=[Text.Encoding]::ASCII.GetBytes($hd);$s.Write($hb,0,$hb.Length);$s.Write($b,0,$b.Length)}else{$b=[IO.File]::ReadAllBytes($f);$hd="HTTP/1.1 200 OK`r`nContent-Type: application/octet-stream`r`nContent-Length: $($b.Length)`r`n`r`n";$hb=[Text.Encoding]::ASCII.GetBytes($hd);$s.Write($hb,0,$hb.Length);$s.Write($b,0,$b.Length)}}else{$b=[Text.Encoding]::UTF8.GetBytes('404');$hd="HTTP/1.1 404 Not Found`r`nContent-Length: $($b.Length)`r`n`r`n";$hb=[Text.Encoding]::ASCII.GetBytes($hd);$s.Write($hb,0,$hb.Length);$s.Write($b,0,$b.Length)};$s.Close();$c.Close()}